choose.when:
SELECT p.id,p.project_id,'PAGE_OBJECT' AS asset_type,p.name,'WEB_UI' AS category,p.status,p.route_pattern AS summary,
       COALESCE(p.update_user,p.create_user) AS owner,p.update_time,CAST(p.version AS CHAR) AS source_version,NULL AS related_id
FROM ai_page_object p WHERE p.project_id=#{projectId}

SELECT b.id,b.project_id,'BUSINESS_FLOW' AS asset_type,b.name,'FLOW' AS category,b.status,b.entry_node_id AS summary,
       COALESCE(b.update_user,b.create_user) AS owner,b.update_time,CAST(b.version AS CHAR) AS source_version,NULL AS related_id
FROM ai_business_flow b WHERE b.project_id=#{projectId}

mapper.sql:
WHERE catalog.asset_type = #{assetType}
AND v.id IS NOT NULL
AND catalog.status = #{status}
AND catalog.update_time >= #{updatedAfter}

    AND COALESCE(m.creation_source, 'UNKNOWN') IN
    #{source}

AND m.category_id = #{categoryId}

    AND (c.id=#{categoryId} OR c.path LIKE CONCAT((SELECT selected.path FROM test_asset_category selected WHERE selected.id=#{categoryId} AND selected.deleted=b'0'), ' / %'))


    AND (LOWER(catalog.id) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(catalog.name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(COALESCE(catalog.summary, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

WHERE d.project_id = #{projectId} AND d.deleted = 0

    AND COALESCE(dm.creation_source,'UNKNOWN') IN
    #{source}

AND dm.category_id=#{categoryId}

    AND (dc.id=#{categoryId} OR dc.path LIKE CONCAT((SELECT path FROM test_asset_category WHERE id=#{categoryId} AND deleted=b'0'),' / %'))


    AND d.parse_status = #{parseStatus}


    AND (LOWER(d.original_name) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(d.id) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(COALESCE(d.summary, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%'))

WHERE v.project_id = #{projectId}
AND v.asset_type IN

    #{allowedType}

AND v.asset_type = #{assetType}
AND v.asset_id = #{assetId}

    AND COALESCE(vm.creation_source,'UNKNOWN') IN
    #{source}

AND vm.category_id=#{categoryId}

    AND (vc.id=#{categoryId} OR vc.path LIKE CONCAT((SELECT path FROM test_asset_category WHERE id=#{categoryId} AND deleted=b'0'),' / %'))


    AND (LOWER(v.asset_id) LIKE CONCAT('%', LOWER(#{keyword}), '%')
         OR LOWER(COALESCE(d.original_name, fc.name, task.name,
            CONCAT('Step ', step_asset.pos, ': ', LEFT(step_asset.instruction, 120)), dataset.name, env.name,
            common_step.name, api_asset.name, evidence.file_name, bug_asset.title, ''))
            LIKE CONCAT('%', LOWER(#{keyword}), '%'))

mapper.select:
SELECT DISTINCT v.id AS versionId, v.asset_id AS documentId, COALESCE(d.original_name, v.asset_id) AS documentName, v.version_no AS versionNo, v.source_version AS sourceVersion, v.content_hash AS contentHash, v.content_snapshot AS contentSnapshot FROM test_asset_relation r JOIN test_asset_version v ON v.id = r.source_version_id AND v.project_id = r.project_id AND v.status = 'PUBLISHED' LEFT JOIN ai_source_document d ON d.id = v.asset_id AND d.project_id = v.project_id WHERE r.project_id = #{projectId} AND r.relation_type = 'DERIVED_FROM' AND r.source_asset_type = 'DOCUMENT' AND r.target_asset_type = 'CASE' AND r.target_asset_id IN
#{caseAssetId}
ORDER BY v.version_no DESC, v.id
